    private enum ExprKind
    {
        Action,
        AndCode,
        And,
        AndLogical,
        Any,
        CharClass,
        Choice,
        Code,
        Labeled,
        Literal,
        NotCode,
        Not,
        NotLogical,
        OneOrMore,
        Recovery,
        RuleRef,
        RuleIndexRef,
        Sequence,
        Throw,
        ZeroOrMore,
        ZeroOrOne,
    }

    private sealed class Grammar
    {
        public List<Rule> Rules = new List<Rule>();
    }

    private sealed class Rule
    {
        public string Name = string.Empty;
        public string? DisplayName;
        public Expr Expr = null!;
        public bool VarExists;
        public Position Pos;
    }

    private readonly struct UnicodeRange
    {
        public UnicodeRange(int lo, int hi, int stride)
        {
            Lo = lo;
            Hi = hi;
            Stride = stride;
        }

        public int Lo { get; }
        public int Hi { get; }
        public int Stride { get; }
    }

    private sealed class Expr
    {
        public ExprKind Kind;
        public Expr? Inner;
        public List<Expr>? Items;
        public Func<PTParser, object?>? ActionRun;
        public Func<PTParser, bool>? PredicateRun;
        public Expr? RecoverExpr;
        public List<string>? FailureLabels;
        public string? Label;
        public bool TextCapture;
        public string? Name;
        public int Index;
        public string? Value;
        public string? Want;
        public int[]? Chars;
        public int[]? Ranges;
        public UnicodeRange[]? Classes;
        public bool IgnoreCase;
        public bool Inverted;
        public bool NotSkip;
